  // Physical stock counts
  if(route==='/api/inventory/counts'&&method==='GET'){const actor=actorFor(viewRoles);const scoped=roleScoped(actor);return json(res,200,list(`SELECT c.*,l.code location_code,l.name location_name FROM stock_counts c JOIN locations l ON l.id=c.location_id WHERE (? IS NULL OR c.location_id=?) ORDER BY c.id DESC`,scoped,scoped));}
  if(route==='/api/inventory/counts'&&method==='POST'){const actor=actorFor(['owner','admin','branch_manager','warehouse_manager']);const b=await readBody(req);const location=locationFor(b.locationCode,actor);if(!Array.isArray(b.lines)||!b.lines.length)throw new HttpError(400,'Physical count must contain at least one SKU line.');const result=transaction(db,()=>{const no=nextNumber('CNT');const id=Number(db.prepare(`INSERT INTO stock_counts(count_number,location_id,status,counted_by,notes) VALUES(?,?,'submitted',?,?)`).run(no,location.id,actor.id,asText(b.notes,400)).lastInsertRowid);const ins=db.prepare('INSERT INTO stock_count_lines(stock_count_id,sku,expected_qty,counted_qty,variance_qty) VALUES(?,?,?,?,?)');for(const line of b.lines){const sku=asText(line.sku,64).toUpperCase();if(!db.prepare('SELECT 1 FROM products WHERE sku=? AND active=1').get(sku))throw new HttpError(404,`SKU ${sku} was not found.`);const counted=Number(line.countedQty);if(!Number.isFinite(counted)||counted<0||Math.abs(counted*1000-Math.round(counted*1000))>1e-7)throw new HttpError(400,`Invalid count quantity for ${sku}.`);const expected=getOnHand(db,sku,location.id);ins.run(id,sku,expected,counted,counted-expected);}audit(db,actor.id,'PHYSICAL_COUNT_SUBMITTED','stock_count',id,{no,location:location.code,lines:b.lines.length});return{id,number:no,status:'submitted'};});return json(res,201,result);}
