  if(route==='/api/inventory/damages'&&method==='POST'){const actor=actorFor(['owner','admin','branch_manager','warehouse_manager']);const b=await readBody(req);const location=locationFor(b.locationCode,actor);const reason=asText(b.reason,300);if(reason.length<5||!Array.isArray(b.lines)||!b.lines.length)throw new HttpError(400,'Enter a damage reason and at least one SKU line.');const lines=b.lines.map(x=>({sku:asText(x.sku,64).toUpperCase(),qty:asQty(x.qty)}));const result=transaction(db,()=>{for(const x of lines)if(availableQty(x.sku,location.id)+1e-9<x.qty)throw new HttpError(409,`Insufficient available stock for ${x.sku}.`);const no=nextNumber('DMG');const id=Number(db.prepare(`INSERT INTO damage_reports(damage_number,location_id,reported_by,reason,status) VALUES(?,?,?,?,'posted')`).run(no,location.id,actor.id,reason).lastInsertRowid);const put=db.prepare('INSERT INTO damage_report_lines(damage_report_id,sku,qty,unit_cost_cents) VALUES(?,?,?,?)');const move=db.prepare(`INSERT INTO inventory_movements(sku,location_id,movement_type,qty_delta,source_type,source_id,note,created_by) VALUES(?,?,'DAMAGE',?,'DAMAGE',?,?,?)`);let cost=0;for(const x of lines){const product=db.prepare('SELECT cost_cents FROM products WHERE sku=?').get(x.sku);if(!product)throw new HttpError(404,`SKU ${x.sku} not found.`);put.run(id,x.sku,x.qty,product.cost_cents);move.run(x.sku,location.id,-x.qty,String(id),reason,actor.id);cost+=Math.round(x.qty*product.cost_cents);}if(cost)postJournal({actorId:actor.id,sourceType:'DAMAGE',sourceId:id,description:`Damage ${no}`,lines:[{accountCode:'5300',debitCents:cost},{accountCode:'1200',creditCents:cost}]});audit(db,actor.id,'DAMAGE_POSTED','damage_report',id,{no,location:location.code,lines});return{id,number:no};});return json(res,201,result);}
  if(route==='/api/pos/returns'&&method==='POST'){const actor=actorFor(['owner','admin','branch_manager','cashier']);const b=await readBody(req);const sale=db.prepare('SELECT * FROM pos_sales WHERE id=?').get(asText(b.saleId,80));if(!sale)throw new HttpError(404,'Original sale not found.');ctx.assertLocationScope(actor,{id:sale.location_id});const reason=asText(b.reason,300);const refundMethod=asText(b.refundMethod||sale.payment_method,30).toUpperCase();if(reason.length<3||!['CASH','CARD','MOBILE_MONEY','BANK_TRANSFER','STORE_CREDIT'].includes(refundMethod)||!Array.isArray(b.lines)||!b.lines.length)throw new HttpError(400,'Provide original sale, return reason, refund method and return lines.');const norm=b.lines.map(x=>({saleLineId:Number(x.saleLineId),qty:asQty(x.qty)}));const result=transaction(db,()=>{const no=nextNumber('RET');let amount=0,cost=0;const resolved=[];for(const x of norm){const saleLine=db.prepare('SELECT sl.*,p.cost_cents FROM pos_sale_lines sl JOIN products p ON p.sku=sl.sku WHERE sl.id=? AND sl.sale_id=?').get(x.saleLineId,sale.id);if(!saleLine)throw new HttpError(400,'Return line does not belong to the selected sale.');const returned=Number(db.prepare('SELECT COALESCE(SUM(qty),0) q FROM sales_return_lines WHERE sale_line_id=?').get(x.saleLineId).q);if(returned+x.qty>saleLine.qty+1e-9)throw new HttpError(409,`Return quantity exceeds sold quantity for ${saleLine.sku}.`);const lineTotal=Math.round(saleLine.unit_price_cents*x.qty);amount+=lineTotal;cost+=Math.round(saleLine.cost_cents*x.qty);resolved.push({...x,saleLine,lineTotal});}const id=Number(db.prepare(`INSERT INTO sales_returns(return_number,sale_id,location_id,reason,refund_method,refund_total_cents,received_by) VALUES(?,?,?,?,?,?,?)`).run(no,sale.id,sale.location_id,reason,refundMethod,amount,actor.id).lastInsertRowid);const put=db.prepare('INSERT INTO sales_return_lines(return_id,sale_line_id,sku,qty,unit_price_cents,line_total_cents) VALUES(?,?,?,?,?,?)');const move=db.prepare(`INSERT INTO inventory_movements(sku,location_id,movement_type,qty_delta,source_type,source_id,note,created_by) VALUES(?,?,'RETURN',?,'RETURN',?,?,?)`);for(const x of resolved){put.run(id,x.saleLine.id,x.saleLine.sku,x.qty,x.saleLine.unit_price_cents,x.lineTotal);move.run(x.saleLine.sku,sale.location_id,x.qty,String(id),`Return ${no}`,actor.id);}const cashCode=refundMethod==='CASH'?'1000':refundMethod==='CARD'?'1020':refundMethod==='MOBILE_MONEY'?'1030':refundMethod==='BANK_TRANSFER'?'1010':'2400';if(!db.prepare('SELECT 1 FROM accounts WHERE account_code=?').get(cashCode)&&cashCode==='2400')db.prepare(`INSERT OR IGNORE INTO accounts(account_code,account_name,account_type,normal_balance) VALUES('2400','Customer Store Credit','liability','credit')`).run();const returnJournalLines=[];if(amount>0)returnJournalLines.push({accountCode:'4010',debitCents:amount},{accountCode:cashCode,creditCents:amount});if(cost>0)returnJournalLines.push({accountCode:'1200',debitCents:cost},{accountCode:'5000',creditCents:cost});if(returnJournalLines.length)postJournal({actorId:actor.id,sourceType:'RETURN',sourceId:id,description:`Sales return ${no}`,lines:returnJournalLines});audit(db,actor.id,'SALES_RETURN_POSTED','sales_return',id,{no,saleId:sale.id,amount});return{id,number:no,refundTotal:centsToAmount(amount)};});return json(res,201,result);}
  if(route==='/api/pos/returns'&&method==='GET'){const actor=actorFor(viewRoles);const scoped=roleScoped(actor);return json(res,200,list(`SELECT r.*,s.external_sale_id,l.code location_code FROM sales_returns r JOIN pos_sales s ON s.id=r.sale_id JOIN locations l ON l.id=r.location_id WHERE (? IS NULL OR r.location_id=?) ORDER BY r.id DESC`,scoped,scoped).map(r=>({...r,refundTotal:centsToAmount(r.refund_total_cents)})));}

