  if(route==='/api/wholesale/orders'&&method==='POST'){const actor=actorFor(['owner','admin','branch_manager','cashier']);const b=await readBody(req);const customer=partyById('customers',b.customerId);const location=locationFor(b.locationCode,actor);if(!Array.isArray(b.lines)||!b.lines.length)throw new HttpError(400,'Wholesale order requires at least one line.');const payMethod=asText(b.paymentMethod||'BANK_TRANSFER',30).toUpperCase();if(!['CASH','CARD','MOBILE_MONEY','BANK_TRANSFER','CREDIT'].includes(payMethod))throw new HttpError(400,'Unsupported wholesale payment method.');const lines=b.lines.map(x=>{const sku=asText(x.sku,64).toUpperCase();const product=db.prepare('SELECT * FROM products WHERE sku=? AND active=1').get(sku);if(!product)throw new HttpError(404,`SKU ${sku} not found.`);const qty=asQty(x.qty);const price=x.unitPrice===undefined?product.wholesale_cents:asMoneyCents(x.unitPrice);return{sku,qty,price,total:Math.round(qty*price),cost:product.cost_cents};});const total=lines.reduce((s,x)=>s+x.total,0);if(total<=0)throw new HttpError(400,'Wholesale order total must be greater than zero.');const no=nextNumber('WHO');const id=Number(db.prepare(`INSERT INTO wholesale_orders(order_number,customer_id,location_id,status,payment_method,total_cents,notes,created_by) VALUES(?,?,?,'draft',?,?,?,?)`).run(no,customer.id,location.id,payMethod,total,asText(b.notes,400),actor.id).lastInsertRowid);const ins=db.prepare('INSERT INTO wholesale_order_lines(wholesale_order_id,sku,qty,unit_price_cents,line_total_cents) VALUES(?,?,?,?,?)');for(const x of lines)ins.run(id,x.sku,x.qty,x.price,x.total);audit(db,actor.id,'WHOLESALE_ORDER_CREATED','wholesale_order',id,{no,total,lines:lines.length});return json(res,201,{id,number:no,total:centsToAmount(total),status:'draft'});}
