  if(wholesaleConfirm&&method==='POST'){const actor=actorFor(['owner','admin','branch_manager']);const id=Number(wholesaleConfirm[1]);const order=db.prepare('SELECT * FROM wholesale_orders WHERE id=?').get(id);if(!order)notFound();ctx.assertLocationScope(actor,{id:order.location_id});if(order.status!=='draft')throw new HttpError(409,'Only draft wholesale orders can be confirmed.');const lines=db.prepare('SELECT wl.*,p.cost_cents FROM wholesale_order_lines wl JOIN products p ON p.sku=wl.sku WHERE wl.wholesale_order_id=?').all(id);const result=transaction(db,()=>{let cogs=0;for(const line of lines){if(availableQty(line.sku,order.location_id)+1e-9<line.qty)throw new HttpError(409,`Insufficient stock for ${line.sku}.`);db.prepare(`INSERT INTO inventory_movements(sku,location_id,movement_type,qty_delta,source_type,source_id,note,created_by) VALUES(?,?,'SALE',?,'WHOLESALE',?,?,?)`).run(line.sku,order.location_id,-line.qty,String(id),`Wholesale ${order.order_number}`,actor.id);cogs+=Math.round(line.qty*line.cost_cents);}db.prepare(`UPDATE wholesale_orders SET status='confirmed',confirmed_by=?,confirmed_at=? WHERE id=?`).run(actor.id,isoNow(),id);const debitCode=order.payment_method==='CREDIT'?'1100':order.payment_method==='CASH'?'1000':order.payment_method==='CARD'?'1020':order.payment_method==='MOBILE_MONEY'?'1030':'1010';postJournal({actorId:actor.id,sourceType:'WHOLESALE',sourceId:id,description:`Wholesale ${order.order_number}`,lines:[{accountCode:debitCode,debitCents:order.total_cents},{accountCode:'4000',creditCents:order.total_cents},...(cogs>0?[{accountCode:'5000',debitCents:cogs},{accountCode:'1200',creditCents:cogs}]:[])]});if(order.payment_method==='CREDIT'){const no=nextNumber('AR');db.prepare(`INSERT INTO customer_invoices(invoice_number,customer_id,invoice_date,total_cents,status,source_type,source_id,created_by) VALUES(?,?,?,?,'open','WHOLESALE',?,?)`).run(no,order.customer_id,today(),order.total_cents,String(id),actor.id);}audit(db,actor.id,'WHOLESALE_ORDER_CONFIRMED','wholesale_order',id,{cogs});return{id,status:'confirmed'};});return json(res,200,result);}

